//! Regional AI search visibility screen with interactive choropleth world map and country rankings.
//!
//! Renders [`BrandRegionsScreen`] inside [`AppShell`] (`"Northwind"` workspace, active
//! `"Answer Engine Insights"`), pairing a multi-continent zoomable world map shaded by
//! visibility, share of voice, or positive sentiment with a synchronized ranked country list,
//! period and dimension filters, and hover/keyboard country inspection cards.

use crate::{
    components::{
        app_shell::{AppShell, AppShellEvent, AppShellLayout, ShellNavGroup, ShellNavItem},
        pro_chrome::{
            ProPalette, pro_check_draw, pro_eid, pro_empty_state, pro_icon_btn, pro_mark_selected,
            pro_mix_color, pro_pill_indicator, pro_popover_presence, pro_rolling_number,
            pro_selection_sensor, pro_skeleton_bar, pro_spring_bar, pro_spring_f32, pro_swap_label,
            pro_tactile, pro_toast_banner, pro_underline_indicator, pro_view_transition, tr,
        },
    },
    foundation::Theme,
    primitives::pro_icons::{ProIcon, pro_icon, pro_raw_svg, pro_svg},
};
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc, sync::OnceLock};
use web_time::Instant;

