/// Top brand insight tabs in [`BrandRegionsScreen`].
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum BrandRegionsTab {
    Visibility,
    Sentiment,
    Topics,
    Platforms,
    #[default]
    Regions,
    Shopping,
    Citations,
}

impl BrandRegionsTab {
    /// Return all 7 brand insight tabs in header order.
    pub const fn all() -> [Self; 7] {
        [
            Self::Visibility,
            Self::Sentiment,
            Self::Topics,
            Self::Platforms,
            Self::Regions,
            Self::Shopping,
            Self::Citations,
        ]
    }

    /// Stable slug token for element ids.
    pub const fn slug(self) -> &'static str {
        match self {
            Self::Visibility => "visibility",
            Self::Sentiment => "sentiment",
            Self::Topics => "topics",
            Self::Platforms => "platforms",
            Self::Regions => "regions",
            Self::Shopping => "shopping",
            Self::Citations => "citations",
        }
    }

    /// Localized display label for the tab strip.
    pub fn label(self, cx: &App) -> &'static str {
        match self {
            Self::Visibility => tr(cx, "Visibility", "可见度"),
            Self::Sentiment => tr(cx, "Sentiment", "情感倾向"),
            Self::Topics => tr(cx, "Topics", "主题"),
            Self::Platforms => tr(cx, "Platforms", "平台"),
            Self::Regions => tr(cx, "Regions", "国家与地区"),
            Self::Shopping => tr(cx, "Shopping", "购物推荐"),
            Self::Citations => tr(cx, "Citations", "引用来源"),
        }
    }
}

/// Time window pills on the [`BrandRegionsScreen`] toolbar.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum BrandRegionsPeriod {
    #[default]
    Days7,
    Days15,
    Days30,
    Custom,
}

impl BrandRegionsPeriod {
    /// Return all selectable period pills in toolbar order.
    pub const fn all() -> [Self; 4] {
        [Self::Days7, Self::Days15, Self::Days30, Self::Custom]
    }

    /// Stable slug token for element ids.
    pub const fn slug(self) -> &'static str {
        match self {
            Self::Days7 => "7d",
            Self::Days15 => "15d",
            Self::Days30 => "30d",
            Self::Custom => "custom",
        }
    }

    /// Localized display label for the period segmented control.
    pub fn label(self, cx: &App) -> &'static str {
        match self {
            Self::Days7 => "7d",
            Self::Days15 => "15d",
            Self::Days30 => "30d",
            Self::Custom => tr(cx, "Custom", "自定义"),
        }
    }

    /// Multiplier applied to base regional percentages for this time window.
    pub const fn scale_factor(self) -> f32 {
        match self {
            Self::Days7 => 1.0,
            Self::Days15 => 0.94,
            Self::Days30 => 0.88,
            Self::Custom => 0.90,
        }
    }
}

/// Active regional metric shaded on the world map and ranked in the side list.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub enum BrandRegionsMeasure {
    #[default]
    Visibility,
    ShareOfVoice,
    Sentiment,
}

impl BrandRegionsMeasure {
    /// Return all three measures in segmented switcher order.
    pub const fn all() -> [Self; 3] {
        [Self::Visibility, Self::ShareOfVoice, Self::Sentiment]
    }

    /// Stable slug token for element ids.
    pub const fn slug(self) -> &'static str {
        match self {
            Self::Visibility => "visibility",
            Self::ShareOfVoice => "sov",
            Self::Sentiment => "sentiment",
        }
    }

    /// Compact button label in the right-hand measure segmented control.
    pub fn short_label(self, cx: &App) -> &'static str {
        match self {
            Self::Visibility => tr(cx, "Visibility", "可见度"),
            Self::ShareOfVoice => tr(cx, "Share of Voice", "声量占比"),
            Self::Sentiment => tr(cx, "Sentiment", "情感度"),
        }
    }

    /// Descriptive column header and tooltip label.
    pub fn long_label(self, cx: &App) -> &'static str {
        match self {
            Self::Visibility => tr(cx, "Visibility", "可见度"),
            Self::ShareOfVoice => tr(cx, "Share of voice", "声量占比"),
            Self::Sentiment => tr(cx, "Positive sentiment", "正面情感度"),
        }
    }
}

/// Geographic viewport preset in the `"Chart config"` menu.
