pub enum BrandMapZoom {
    #[default]
    World,
    Americas,
    Europe,
    Asia,
}

impl BrandMapZoom {
    /// Return all zoom presets in menu order.
    pub const fn all() -> [Self; 4] {
        [Self::World, Self::Americas, Self::Europe, Self::Asia]
    }

    /// Stable slug token for element ids.
    pub const fn slug(self) -> &'static str {
        match self {
            Self::World => "world",
            Self::Americas => "americas",
            Self::Europe => "europe",
            Self::Asia => "asia",
