}

/// Point-change deltas (percentage points vs. prior period) for a [`BrandRegionRow`].
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct BrandRegionDeltas {
    pub visibility: f32,
    pub sov: f32,
    pub sentiment: f32,
}

impl BrandRegionDeltas {
    /// Construct period-over-period point changes for all three measures.
    pub const fn new(visibility: f32, sov: f32, sentiment: f32) -> Self {
        Self {
            visibility,
            sov,
            sentiment,
        }
    }

    /// Read the delta corresponding to `measure`.
    pub const fn get(self, measure: BrandRegionsMeasure) -> f32 {
        match measure {
            BrandRegionsMeasure::Visibility => self.visibility,
            BrandRegionsMeasure::ShareOfVoice => self.sov,
            BrandRegionsMeasure::Sentiment => self.sentiment,
        }
    }
}

/// Regional AI answer metrics for one country (`id` is ISO 3166-1 numeric code, e.g. `"840"`).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct BrandRegionRow {
    pub id: SharedString,
    pub name: SharedString,
    pub flag: SharedString,
    pub visibility: f32,
    pub sov: f32,
    pub sentiment: f32,
    pub change: BrandRegionDeltas,
}

impl BrandRegionRow {
    /// Construct a country metric entry.
    pub fn new(
        id: impl Into<SharedString>,
        name: impl Into<SharedString>,
        flag: impl Into<SharedString>,
        visibility: f32,
        sov: f32,
        sentiment: f32,
        change: BrandRegionDeltas,
    ) -> Self {
        Self {
            id: id.into(),
            name: name.into(),
            flag: flag.into(),
            visibility,
            sov,
            sentiment,
            change,
        }
    }

    /// Read the percentage value for `measure`.
    pub const fn metric(&self, measure: BrandRegionsMeasure) -> f32 {
        match measure {
            BrandRegionsMeasure::Visibility => self.visibility,
            BrandRegionsMeasure::ShareOfVoice => self.sov,
            BrandRegionsMeasure::Sentiment => self.sentiment,
        }
    }
}

/// Typed events emitted by [`BrandRegionsScreen`].
#[derive(Clone, Debug, PartialEq)]
pub enum BrandRegionsEvent {
    Navigate(SharedString),
    TabChanged(BrandRegionsTab),
    PeriodChanged(BrandRegionsPeriod),
    MeasureChanged(BrandRegionsMeasure),
    ZoomChanged(BrandMapZoom),
    ShadingToggled(bool),
    FiltersChanged {
        tags: Vec<SharedString>,
        topics: Vec<SharedString>,
        platforms: Vec<SharedString>,
    },
    OpenAnswers,
    ExportCsv,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum OpenPopover {
    More,
    Tags,
    Topics,
    Platforms,
    ChartConfig,
}

fn format_pct(v: f32) -> String {
    if v.is_finite() {
        format!("{v:.1}%")
    } else {
        "–".to_owned()
    }
}

fn format_delta_pct(v: f32) -> String {
    if !v.is_finite() {
        return "–".to_owned();
    }
    if v.abs() < 0.05 {
        "0.0%".to_owned()
    } else if v > 0.0 {
        format!("+{:.1}%", v.abs())
    } else {
        format!("−{:.1}%", v.abs())
    }
}

fn format_answers_count(count: u64) -> String {
    let f = count as f64;
    if f >= 999_950.0 {
        let s = format!("{:.1}", f / 1_000_000.0);
        format!("{}M", s.strip_suffix(".0").unwrap_or(&s))
    } else if f >= 1_000.0 {
        let s = format!("{:.1}", f / 1_000.0);
        format!("{}k", s.strip_suffix(".0").unwrap_or(&s))
    } else {
        format!("{count}")
    }
}

