        "jp" => Some(FLAG_JP_SVG),
        "ca" => Some(FLAG_CA_SVG),
        "au" => Some(FLAG_AU_SVG),
        _ => None,
    };
    let mut wrap = div()
        .w(px(16.))
        .h(px(11.))
        .flex_none()
        .rounded(px(2.5))
        .overflow_hidden()
        .border_1()
        .border_color(if p.dark {
            hsla(0., 0., 1., 0.14)
        } else {
            hsla(0., 0., 0., 0.14)
        });
    if let Some(svg) = markup {
        wrap = wrap.child(pro_raw_svg(svg, 16., 11.));
    } else {
        wrap = wrap.bg(p.chip_hover);
    }
    wrap
}

