fn country_continent_zoom(country_id: &str) -> BrandMapZoom {
    let Some(&(_, cx, cy, _)) = WORLD_COUNTRIES
        .iter()
        .find(|&&(id, _, _, _)| id == country_id)
    else {
        return BrandMapZoom::World;
    };
    if cx < 440 {
        BrandMapZoom::Americas
    } else if cx < 620 && cy < 140 {
        BrandMapZoom::Europe
    } else if cx > 630 {
        BrandMapZoom::Asia
    } else {
        BrandMapZoom::World
    }
}

fn point_in_svg_subpaths(px_x: f32, px_y: f32, d: &str) -> bool {
    let mut inside = false;
    for subpath in d.split('Z') {
        let sub = subpath.trim();
        if sub.is_empty() {
            continue;
        }
        let mut pts: Vec<(f32, f32)> = Vec::with_capacity(32);
        for seg in sub.split(['M', 'L']) {
            let s = seg.trim();
            if s.is_empty() {
                continue;
            }
            if let Some((xs, ys)) = s.split_once(',')
                && let (Ok(x), Ok(y)) = (xs.trim().parse::<f32>(), ys.trim().parse::<f32>())
            {
                pts.push((x, y));
            }
        }
        if pts.len() < 3 {
            continue;
        }
        let mut j = pts.len() - 1;
        for i in 0..pts.len() {
            let (xi, yi) = pts[i];
            let (xj, yj) = pts[j];
            let intersects =
                ((yi > px_y) != (yj > px_y)) && (px_x < (xj - xi) * (px_y - yi) / (yj - yi) + xi);
            if intersects {
                inside = !inside;
            }
            j = i;
        }
    }
    inside
}

fn hit_test_data_country(
    map_x: f32,
    map_y: f32,
    scaled_rows: &[BrandRegionRow],
) -> Option<SharedString> {
    for row in scaled_rows {
        for &(id, _, _, path_d) in WORLD_COUNTRIES {
            if id == row.id.as_ref() && point_in_svg_subpaths(map_x, map_y, path_d) {
                return Some(row.id.clone());
            }
        }
    }
    None
}

type CountryRings = Vec<Vec<(f32, f32)>>;

fn parse_country_rings(d: &str) -> CountryRings {
    let mut rings = Vec::new();
    for subpath in d.split('Z') {
        let sub = subpath.trim();
        if sub.is_empty() {
            continue;
        }
        let mut pts: Vec<(f32, f32)> = Vec::with_capacity(32);
        for seg in sub.split(['M', 'L']) {
            let s = seg.trim();
            if s.is_empty() {
                continue;
            }
            if let Some((xs, ys)) = s.split_once(',')
                && let (Ok(x), Ok(y)) = (xs.trim().parse::<f32>(), ys.trim().parse::<f32>())
            {
                pts.push((x, y));
            }
        }
        if pts.len() >= 3 {
            rings.push(pts);
        }
    }
    rings
}

fn parsed_world_countries() -> &'static Vec<(&'static str, CountryRings)> {
    static PARSED: OnceLock<Vec<(&'static str, CountryRings)>> = OnceLock::new();
    PARSED.get_or_init(|| {
        WORLD_COUNTRIES
            .iter()
            .map(|&(cid, _, _, d)| (cid, parse_country_rings(d)))
            .collect()
    })
}

#[allow(clippy::too_many_arguments)]
fn paint_country_rings(
    rings: &[Vec<(f32, f32)>],
    origin_x: f32,
    origin_y: f32,
    vx: f32,
    vy: f32,
    scale: f32,
    fill_color: Hsla,
    stroke_color: Hsla,
    stroke_px: f32,
    window: &mut Window,
) {
    let mut fill_pb = PathBuilder::fill();
    for pts in rings {
        for (i, &(mx, my)) in pts.iter().enumerate() {
            let pt = point(
                px(origin_x + (mx - vx) * scale),
                px(origin_y + (my - vy) * scale),
            );
            if i == 0 {
                fill_pb.move_to(pt);
            } else {
                fill_pb.line_to(pt);
            }
        }
        fill_pb.close();
    }
    if let Ok(path) = fill_pb.build() {
        window.paint_path(path, fill_color);
    }

    if stroke_px > 0.05 {
        let mut stroke_pb = PathBuilder::stroke(px(stroke_px));
        for pts in rings {
            for (i, &(mx, my)) in pts.iter().enumerate() {
                let pt = point(
                    px(origin_x + (mx - vx) * scale),
                    px(origin_y + (my - vy) * scale),
                );
                if i == 0 {
                    stroke_pb.move_to(pt);
                } else {
                    stroke_pb.line_to(pt);
                }
            }
            stroke_pb.close();
        }
        if let Ok(path) = stroke_pb.build() {
            window.paint_path(path, stroke_color);
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn paint_world_map_canvas(
    bounds: Bounds<Pixels>,
    dark: bool,
    view_box: [f32; 4],
    shading: bool,
    skeleton: bool,
    empty: bool,
    hovered_id: Option<&str>,
    scaled_rows: &[BrandRegionRow],
    measure: BrandRegionsMeasure,
    alpha_mul: f32,
    window: &mut Window,
) {
    let [vx, vy, vw, vh] = view_box;
    let bw = f32::from(bounds.size.width);
    let bh = f32::from(bounds.size.height);
    if bw <= 4.0 || bh <= 4.0 || vw <= 1.0 || vh <= 1.0 {
        return;
    }
    let scale = (bw / vw).min(bh / vh);
    let origin_x = f32::from(bounds.left());
    let origin_y = f32::from(bounds.top());

    let card_bg: Hsla = if dark {
        rgb(0x1b1b1e).into()
    } else {
        rgb(0xffffff).into()
    };
    let land_base = if dark {
        pro_mix_color(card_bg, rgb(0xffffff).into(), 0.085)
    } else {
        pro_mix_color(card_bg, rgb(0x000000).into(), 0.07)
    };
    let skel_fill = if dark {
        pro_mix_color(card_bg, rgb(0xffffff).into(), 0.07)
    } else {
        pro_mix_color(card_bg, rgb(0x000000).into(), 0.055)
    };
    let br_blue: Hsla = if dark {
        rgb(0x4d8dff).into()
    } else {
        rgb(0x0060e2).into()
    };

    let base_stroke_px = (0.55 * (vw / 680.0) * scale).clamp(0.45, 1.15);
    let active_stroke_px = (1.25 * (vw / 680.0) * scale).clamp(1.0, 2.0);

    let mut max_val = 1.0f32;
    for r in scaled_rows {
        let v = r.metric(measure).max(0.0);
        if v > max_val {
            max_val = v;
        }
    }

    let has_hover = hovered_id.is_some() && !skeleton && !empty;
    let mut active_overlay: Option<(&CountryRings, Hsla)> = None;

    window.paint_layer(bounds, |window| {
        for (cid, rings) in parsed_world_countries() {
            if skeleton {
                paint_country_rings(
                    rings,
                    origin_x,
                    origin_y,
                    vx,
                    vy,
                    scale,
                    skel_fill.opacity(alpha_mul),
                    card_bg,
                    base_stroke_px,
                    window,
                );
                continue;
            }
            let region = if empty {
                None
            } else {
                scaled_rows.iter().find(|r| r.id.as_ref() == *cid)
            };
            let is_on = hovered_id == Some(*cid) && region.is_some();
            let raw_fill = if let Some(reg) = region {
                let alpha = if is_on {
                    0.90
                } else if shading {
                    0.18 + (reg.metric(measure).max(0.0) / max_val) * 0.62
                } else {
                    0.36
                };
                pro_mix_color(card_bg, br_blue, alpha)
            } else {
                land_base
            };
            let final_fill = if has_hover && !is_on {
                pro_mix_color(card_bg, raw_fill, 0.55)
            } else {
                raw_fill
            }
            .opacity(alpha_mul);

            if is_on {
                active_overlay = Some((rings, final_fill));
            } else {
                paint_country_rings(
                    rings,
                    origin_x,
                    origin_y,
                    vx,
                    vy,
                    scale,
                    final_fill,
                    card_bg,
                    base_stroke_px,
                    window,
                );
            }
        }

        if let Some((rings, fill_col)) = active_overlay {
            paint_country_rings(
                rings,
                origin_x,
                origin_y,
                vx,
                vy,
                scale,
                fill_col,
                br_blue.opacity(alpha_mul),
                active_stroke_px,
                window,
            );
        }
    });
}

