}

impl EventEmitter<BrandRegionsEvent> for BrandRegionsScreen {}

impl Focusable for BrandRegionsScreen {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus.clone()
    }
}

impl BrandRegionsScreen {
    /// Construct a [`BrandRegionsScreen`] framed inside [`AppShell`] (`"Northwind"` workspace).
    pub fn new(id: impl Into<SharedString>, cx: &mut Context<Self>) -> Self {
        cx.observe_global::<crate::primitives::control::UiLanguage>(|_, cx| cx.notify())
            .detach();
        Self::build(id.into(), false, cx)
    }

    /// Construct [`BrandRegionsScreen`] without the outer [`AppShell`] sidebar.
    pub fn standalone(id: impl Into<SharedString>, cx: &mut Context<Self>) -> Self {
        Self::build(id.into(), true, cx)
    }

    fn build(id_str: SharedString, standalone: bool, cx: &mut Context<Self>) -> Self {
        cx.observe_global::<Theme>(|_, cx| cx.notify()).detach();
        cx.observe_global::<crate::primitives::control::UiLanguage>(|_, cx| cx.notify())
            .detach();
        let this = cx.entity();
        let shell = cx.new(|shell_cx| {
            let active: SharedString =
                tr(shell_cx, "Answer Engine Insights", "答案引擎洞察").into();
            let mut s = AppShell::new(format!("{id_str}-shell"), shell_cx)
                .with_workspace("Northwind")
                .with_user("Alex Morgan", "alex@northwind.ai")
                .with_groups(build_northwind_sidebar(shell_cx))
                .with_active(active)
                .with_side_cards(true)
                .with_work_area(false, false);
            s.bind_page(&this, shell_cx, |screen, w, cx| {
                screen.render_page(w, cx).into_any_element()
            });
            s
        });

        cx.subscribe(&shell, |_, _, ev: &AppShellEvent, cx| {
            if let AppShellEvent::Navigate(label) = ev {
                cx.emit(BrandRegionsEvent::Navigate(label.clone()));
                cx.notify();
            }
        })
        .detach();

        Self {
            id: ElementId::Name(id_str),
            standalone,
            layout: AppShellLayout::Inset,
            shell,
            focus: cx.focus_handle().tab_stop(true),
            list_focus: cx.focus_handle().tab_stop(true),
            workspace: "Northwind".into(),
            user_name: "Alex Morgan".into(),
            user_email: "alex@northwind.ai".into(),
            brand: None,
            regions: default_regions(),
            answers: 5_600,
            date_label: "Nov 23".into(),
            active_tab: BrandRegionsTab::Regions,
            period: BrandRegionsPeriod::Days7,
            measure: BrandRegionsMeasure::Visibility,
            zoom: BrandMapZoom::World,
            shading: true,
            hovered_id: None,
            focused_row_idx: 0,
            selected_tags: Vec::new(),
            selected_topics: Vec::new(),
            selected_platforms: Vec::new(),
            open_popover: None,
            last_popover: None,
            loading: false,
            empty: false,
            toast: None,
            stage_bounds: Rc::new(Cell::new(None)),
            page_bounds: Rc::new(Cell::new(None)),
            anchor_more: Rc::new(Cell::new(None)),
            anchor_tags: Rc::new(Cell::new(None)),
            anchor_topics: Rc::new(Cell::new(None)),
            anchor_platforms: Rc::new(Cell::new(None)),
            anchor_config: Rc::new(Cell::new(None)),
            measured_width: Rc::new(Cell::new(666.)),
            boot_at: Instant::now(),
        }
    }

