    pub fn toggle_country_zoom(&mut self, country_id: &str, cx: &mut Context<Self>) {
        let target = country_continent_zoom(country_id);
        let next = if self.zoom == target {
            BrandMapZoom::World
        } else {
            target
        };
        self.set_zoom(next, cx);
    }

    /// Return whether value-proportional map shading is enabled.
    pub const fn is_shading(&self) -> bool {
        self.shading
    }

    /// Toggle value-proportional map shading vs. single-tone fill.
    pub fn set_shading(&mut self, shading: bool, cx: &mut Context<Self>) {
        self.open_popover = None;
        if self.shading != shading {
            self.shading = shading;
            cx.emit(BrandRegionsEvent::ShadingToggled(shading));
        }
        cx.notify();
    }

    fn refresh_shell(&self, cx: &mut Context<Self>) {
        let ws = self.workspace.clone();
        let name = self.user_name.clone();
        let email = self.user_email.clone();
        let layout = self.layout;
        let shell_id = format!("{}-shell", self.id);
        let this = cx.entity();
        self.shell.update(cx, |s, shell_cx| {
            let active: SharedString =
                tr(shell_cx, "Answer Engine Insights", "答案引擎洞察").into();
            let mut next = AppShell::new(shell_id, shell_cx)
                .with_layout(layout)
                .with_workspace(ws)
                .with_user(name, email)
                .with_groups(build_northwind_sidebar(shell_cx))
                .with_active(active)
                .with_side_cards(true)
                .with_work_area(false, false);
            next.bind_page(&this, shell_cx, |screen, w, cx| {
                screen.render_page(w, cx).into_any_element()
            });
            *s = next;
        });
    }

    fn select_tab(&mut self, tab: BrandRegionsTab, cx: &mut Context<Self>) {
        self.active_tab = tab;
        cx.emit(BrandRegionsEvent::TabChanged(tab));
        if tab != BrandRegionsTab::Regions {
            let msg = format!(
                "{} {}",
                tab.label(cx),
                tr(
                    cx,
                    "opens here – this screen shows Regions",
                    "将在此打开 — 当前界面展示国家与地区",
                )
            );
            self.toast = Some((msg.into(), Instant::now()));
        }
        cx.notify();
    }

    fn toggle_filter_value(list: &mut Vec<SharedString>, item: SharedString) {
        if let Some(pos) = list.iter().position(|x| x == &item) {
            list.remove(pos);
        } else {
            list.push(item);
        }
    }

    fn emit_filters_changed(&mut self, cx: &mut Context<Self>) {
        cx.emit(BrandRegionsEvent::FiltersChanged {
            tags: self.selected_tags.clone(),
            topics: self.selected_topics.clone(),
            platforms: self.selected_platforms.clone(),
        });
        cx.notify();
    }

    /// Compute scaled and sorted regional rows for the current period, filters, and measure.
    pub fn ranked_regions(&self) -> Vec<BrandRegionRow> {
        if self.empty {
            return Vec::new();
        }
        let filter_count =
            self.selected_tags.len() + self.selected_topics.len() + self.selected_platforms.len();
        let factor =
            (self.period.scale_factor() * (1.0 - 0.04 * filter_count as f32)).clamp(0.25, 1.5);
        let mut rows: Vec<BrandRegionRow> = self
            .regions
            .iter()
            .map(|r| {
                let mut copy = r.clone();
                copy.visibility = r.visibility * factor;
                copy.sov = r.sov * factor;
                copy.sentiment = (r.sentiment * (0.5 + factor * 0.5)).min(100.0);
                copy
            })
            .collect();
        let measure = self.measure;
        rows.sort_by(|a, b| {
            b.metric(measure)
                .max(0.0)
                .total_cmp(&a.metric(measure).max(0.0))
        });
        rows
    }

    #[allow(clippy::too_many_arguments)]
    fn render_filter_trigger(
        &self,
        id_suffix: &'static str,
        pop: OpenPopover,
        label: &'static str,
        icon_svg: &'static str,
        count: usize,
        anchor_cell: Rc<Cell<Option<Bounds<Pixels>>>>,
        br_blue: Hsla,
        cx: &Context<Self>,
    ) -> Stateful<Div> {
        let p = ProPalette::get(cx);
        let is_open = self.open_popover == Some(pop);
        let border = if is_open || count > 0 {
            p.line_strong
        } else {
            p.line
        };
        let inner = div()
            .h(px(28.))
            .px(px(10.))
            .flex()
            .items_center()
            .gap(px(6.))
            .text_size(px(13.))
            .font_weight(FontWeight::MEDIUM)
            .text_color(p.ink)
            .whitespace_nowrap()
            .child(pro_svg("0 0 24 24", icon_svg, 14., p.muted))
            .child(label)
            .when(count > 0, |d| {
                d.child(
                    div()
                        .min_w(px(16.))
                        .h(px(16.))
                        .px(px(4.))
                        .rounded(px(4.))
                        .bg(br_blue.opacity(0.12))
                        .flex()
                        .items_center()
                        .justify_center()
                        .child(pro_swap_label(
                            pro_eid(&self.id, format!("flt-cnt-{id_suffix}")),
                            format!("{count}"),
                            11.,
                            FontWeight::MEDIUM,
                            br_blue,
                        )),
                )
            })
            .child(pro_icon(ProIcon::ChevronDown, 12., p.muted));

        pro_tactile(
            pro_eid(&self.id, format!("flt-{id_suffix}")),
            label,
            6.,
            p.card,
            p.hover,
            border,
            p.line_strong,
            is_open || count > 0,
            inner,
            cx,
            move |this, _, cx| {
                if this.open_popover == Some(pop) {
                    this.open_popover = None;
                } else {
                    this.open_popover = Some(pop);
                    this.last_popover = Some(pop);
                }
                cx.notify();
            },
        )
        .relative()
        .flex_none()
        .child(
            canvas(
                move |bounds, _, _| anchor_cell.set(Some(bounds)),
                |_, _, _, _| (),
            )
            .absolute()
            .inset_0(),
        )
    }

    fn render_popover_overlay(
