        let pb = self.page_bounds.get()?;
        let p = ProPalette::get(cx);
        let br_blue: Hsla = if p.dark {
            rgb(0x4d8dff).into()
        } else {
            rgb(0x0060e2).into()
        };
        let page_w = f32::from(pb.size.width);

        let (anchor, align_end, min_w) = match pop {
            OpenPopover::More => (self.anchor_more.get()?, true, 184.0),
            OpenPopover::Tags => (self.anchor_tags.get()?, true, 188.0),
            OpenPopover::Topics => (self.anchor_topics.get()?, true, 196.0),
            OpenPopover::Platforms => (self.anchor_platforms.get()?, true, 196.0),
            OpenPopover::ChartConfig => (self.anchor_config.get()?, false, 236.0),
