        });

        let pop_presence =
            pro_popover_presence(pro_eid(&self.id, "br-pop-pres"), is_open, move || {
                panel.into_any_element()
            });

        Some(
            deferred(
                div()
                    .absolute()
                    .inset_0()
                    .when_some(scrim, |d, s| d.child(s))
                    .child(
                        div()
                            .absolute()
                            .left(px(left_px))
                            .top(px(top_px))
                            .child(pop_presence),
                    ),
            )
            .with_priority(8)
            .into_any_element(),
        )
    }

    fn render_page(&mut self, w: &mut Window, cx: &mut Context<Self>) -> Stateful<Div> {
        let p = ProPalette::get(cx);
        let reduced = Theme::global(cx).reduced_motion;
        let width = self.measured_width.get();
        let stack_layout = width < 540.0;
        let compact_split = width < 780.0;
        let mobile = width < 500.0;

        if let Some(cur_pop) = self.open_popover {
            self.last_popover = Some(cur_pop);
        }

        let elapsed = self.boot_at.elapsed().as_secs_f32();
        let skel_phase = if reduced {
            0.25
        } else {
            (elapsed / 1.6).fract()
        };
        if self.loading && !reduced {
            w.request_animation_frame();
        }
        let map_pulse = if !self.loading || reduced {
            1.0
        } else {
            0.55 + 0.45 * (0.5 + 0.5 * (elapsed * std::f32::consts::TAU / 1.6).cos())
        };

        let br_blue: Hsla = if p.dark {
            rgb(0x4d8dff).into()
        } else {
            rgb(0x0060e2).into()
        };
        let up_color: Hsla = if p.dark {
            rgb(0x3dd68c).into()
        } else {
            rgb(0x12a150).into()
        };
        let down_color: Hsla = if p.dark {
            rgb(0xff6369).into()
        } else {
            rgb(0xe5484d).into()
        };

        let scaled_rows = self.ranked_regions();
        let mut max_val = 0.0f32;
        for r in &scaled_rows {
            max_val = max_val.max(r.metric(self.measure));
        }

        let brand_heading: SharedString = self
            .brand
            .clone()
            .unwrap_or_else(|| tr(cx, "Brand", "品牌洞察").into());

        // Top tab strip with sliding underline indicator
        let tab_sensor = pro_selection_sensor();
        let tabs_strip = div()
            .id(pro_eid(&self.id, "tabs-strip"))
            .role(Role::TabList)
            .aria_label(format!("{brand_heading} insights"))
            .relative()
            .flex_1()
            .min_w_0()
            .overflow_x_scroll()
            .flex()
            .items_center()
            .gap(px(if compact_split { 4. } else { 12. }))
            .on_key_down(cx.listener(|this, ev: &KeyDownEvent, _, cx| {
                let all = BrandRegionsTab::all();
                let pos = all.iter().position(|&t| t == this.active_tab).unwrap_or(4);
                match ev.keystroke.key.as_str() {
                    "left" => {
                        let next = all[(pos + all.len() - 1) % all.len()];
                        this.select_tab(next, cx);
                        cx.stop_propagation();
                    }
                    "right" => {
                        let next = all[(pos + 1) % all.len()];
                        this.select_tab(next, cx);
                        cx.stop_propagation();
                    }
                    _ => {}
                }
            }))
            .child(pro_underline_indicator(
                pro_eid(&self.id, "tabs-uline"),
                self.active_tab.slug(),
                tab_sensor.clone(),
                1.5,
                p.strong,
            ))
            .children(BrandRegionsTab::all().into_iter().map(|tab| {
                let selected = self.active_tab == tab;
                let lbl = tab.label(cx);
                pro_tactile(
                    pro_eid(&self.id, format!("tab-{}", tab.slug())),
                    lbl,
                    6.,
                    transparent_black(),
                    p.hover,
                    transparent_black(),
                    transparent_black(),
                    false,
                    div()
                        .h(px(40.))
                        .px(px(if compact_split { 3.5 } else { 6. }))
                        .flex()
                        .items_center()
                        .whitespace_nowrap()
                        .flex_shrink_0()
                        .text_size(px(if compact_split { 12. } else { 13. }))
                        .text_color(if selected { p.strong } else { p.muted })
                        .when(selected, |d| d.font_weight(FontWeight::MEDIUM))
                        .child(lbl),
                    cx,
                    move |this, _, cx| this.select_tab(tab, cx),
                )
                .relative()
                .flex_shrink_0()
                .when(selected, |d| d.child(pro_mark_selected(&tab_sensor)))
            }));

        let anchor_more = self.anchor_more.clone();
        let more_open = self.open_popover == Some(OpenPopover::More);
        let more_btn = div()
            .relative()
            .flex_none()
            .child(
                canvas(
                    move |bounds, _, _| anchor_more.set(Some(bounds)),
                    |_, _, _, _| (),
                )
                .absolute()
                .inset_0(),
            )
            .child(pro_icon_btn(
                pro_eid(&self.id, "more-btn"),
                tr(cx, "More", "更多操作"),
                ProIcon::MoreHorizontal,
                28.,
                more_open,
                cx,
                |this, _, cx| {
                    if this.open_popover == Some(OpenPopover::More) {
                        this.open_popover = None;
                    } else {
                        this.open_popover = Some(OpenPopover::More);
                        this.last_popover = Some(OpenPopover::More);
                    }
                    cx.notify();
                },
            ));

        let answers_txt: SharedString = if self.loading {
            format!("– {}", tr(cx, "answers", "条回答")).into()
        } else {
            format!(
                "{} {}",
                format_answers_count(self.answers),
                tr(cx, "answers", "条回答")
            )
            .into()
        };
        let answers_btn = pro_tactile(
            pro_eid(&self.id, "answers-btn"),
            answers_txt.clone(),
            6.,
            p.card,
            p.hover,
            p.line,
            p.line_strong,
            false,
            div()
                .h(px(28.))
                .px(px(if compact_split { 8. } else { 10. }))
