                                    pro_eid(&base_id, format!("br-tip-num-{}", m.slug())),
                                    m_val as f64,
                                    1,
                                    "",
                                    "%",
                                    12.,
                                    if on {
                                        FontWeight::MEDIUM
                                    } else {
                                        FontWeight::NORMAL
                                    },
                                    if on { p.strong } else { p.ink },
                                ),
                            ))
                            .into_any_element()
                    })
                    .collect();

            div()
                .absolute()
                .left(px(glide_tx))
                .top(px(glide_ty))
                .child(pro_popover_presence(
                    pro_eid(&self.id, "map-tooltip-pres"),
