                                    .pb(px(8.))
                                    .border_b_1()
                                    .border_color(p.line)
                                    .flex()
                                    .items_center()
                                    .gap(px(8.))
                                    .child(render_country_flag(&region.flag, p))
                                    .child(div().flex_1().min_w_0().truncate().child(
