            .on_mouse_move(cx.listener({
                let hit_rows = hit_rows.clone();
                move |this, ev: &MouseMoveEvent, _, cx| {
                    if this.loading || this.empty {
                        return;
                    }
                    let Some(sb) = this.stage_bounds.get() else {
                        return;
                    };
                    let lx = f32::from(ev.position.x - sb.left());
                    let ly = f32::from(ev.position.y - sb.top());
                    let mx = vx + (lx - map_left) / fit_scale.max(0.001);
                    let my = vy + (ly - map_top) / fit_scale.max(0.001);
                    let hit = hit_test_data_country(mx, my, &hit_rows);
