            skel_col.into_any_element()
        } else if scaled_rows.is_empty() {
            pro_empty_state(
                ProIcon::List,
                tr(cx, "No regions yet", "暂无地区排名"),
                tr(
                    cx,
                    "Countries show up as answers come in from them.",
                    "收到来自各国的回答后，排名列表将自动展示。",
                ),
                None,
                cx,
            )
            .into_any_element()
        } else {
            let mut rows_col = div().flex().flex_col();
            let safe_max = max_val.max(1.0);
            for (ri, row) in scaled_rows.iter().enumerate() {
                let val = row.metric(self.measure);
                let delta = row.change.get(self.measure);
                let delta_color = if delta >= 0.05 {
                    up_color
                } else if delta <= -0.05 {
                    down_color
                } else {
                    p.muted
                };
                let is_on = self.hovered_id.as_ref() == Some(&row.id);
                let row_id = row.id.clone();
                let row_id_hover = row.id.clone();
                let aria = format!(
                    "{}: {} {}, {} on the period before",
                    row.name,
                    self.measure.long_label(cx),
                    format_pct(val),
                    format_delta_pct(delta),
                );
                let bar_ratio = (val / safe_max).clamp(0.0, 1.0);
                let row_content = div()
                    .h(px(40.))
                    .px(px(8.))
                    .flex()
                    .items_center()
                    .justify_between()
                    .gap(px(8.))
                    .text_size(px(13.))
                    .text_color(p.ink)
                    .child(
                        div()
                            .min_w_0()
                            .flex_1()
                            .flex()
                            .flex_col()
                            .gap(px(4.))
                            .child(
                                div()
                                    .flex()
                                    .items_center()
                                    .gap(px(8.))
                                    .child(render_country_flag(&row.flag, p))
                                    .child(div().min_w_0().truncate().child(row.name.clone())),
                            )
                            .child(pro_spring_bar(
                                pro_eid(&self.id, format!("br-rbar-{}", row.id)),
                                bar_ratio,
                                3.0,
                                1.5,
                                p.chip,
                                if is_on {
                                    br_blue
                                } else {
                                    br_blue.opacity(0.65)
                                },
                            )),
                    )
                    .child(
                        div()
                            .flex_none()
                            .flex()
                            .items_center()
                            .gap(px(if compact_split { 8. } else { 10. }))
                            .child(div().min_w(px(42.)).flex().justify_end().child(
                                pro_rolling_number(
                                    pro_eid(&self.id, format!("br-rval-{}", row.id)),
                                    val as f64,
                                    1,
                                    "",
                                    "%",
                                    13.,
                                    FontWeight::MEDIUM,
                                    p.strong,
                                ),
                            ))
                            .child(div().min_w(px(44.)).flex().justify_end().child(
                                pro_swap_label(
                                    pro_eid(&self.id, format!("br-rdel-{}", row.id)),
                                    format_delta_pct(delta),
                                    12.5,
                                    FontWeight::NORMAL,
                                    delta_color,
                                ),
                            )),
                    );

                let btn = pro_tactile(
                    pro_eid(&self.id, format!("region-row-{}", row.id)),
                    aria,
                    6.,
                    transparent_black(),
                    p.hover,
                    transparent_black(),
                    if is_on {
                        br_blue.opacity(0.28)
                    } else {
                        transparent_black()
                    },
                    is_on,
                    row_content,
                    cx,
                    move |this, _, cx| {
                        this.focused_row_idx = ri;
                        this.hovered_id = Some(row_id.clone());
                        this.toggle_country_zoom(&row_id, cx);
                    },
                )
                .w_full()
                .on_hover(cx.listener(move |this, inside: &bool, _, cx| {
                    if *inside {
                        this.hovered_id = Some(row_id_hover.clone());
                        this.focused_row_idx = ri;
                    } else if this.hovered_id.as_ref() == Some(&row_id_hover) {
                        this.hovered_id = None;
                    }
                    cx.notify();
                }));

                rows_col = rows_col.child(
                    div()
                        .when(ri > 0 && !is_on, |d| d.border_t_1().border_color(p.line))
                        .child(btn),
                );
            }
            pro_view_transition(
                pro_eid(&self.id, "regions-list-tx"),
                self.measure.slug(),
                rows_col,
            )
        };

        let key_rows = scaled_rows.clone();
        let list_scroll = div()
            .id(pro_eid(&self.id, "regions-scroll"))
            .track_focus(&self.list_focus)
            .role(Role::List)
            .aria_label(format!(
                "Regions by {}",
                self.measure.long_label(cx).to_ascii_lowercase()
            ))
            .flex_1()
            .min_h_0()
            .when(stack_layout, |d| d.max_h(px(420.)))
            .overflow_y_scroll()
            .focus_visible(move |s| s.rounded(px(6.)).border_1().border_color(p.focus))
            .on_key_down(cx.listener(move |this, ev: &KeyDownEvent, _, cx| {
                if key_rows.is_empty() {
                    return;
                }
                let last = key_rows.len() - 1;
                let cur = this.focused_row_idx.min(last);
                match ev.keystroke.key.as_str() {
                    "down" => {
                        let next = (cur + 1).min(last);
                        this.focused_row_idx = next;
                        this.hovered_id = Some(key_rows[next].id.clone());
                        cx.stop_propagation();
                        cx.notify();
                    }
                    "up" => {
                        let next = cur.saturating_sub(1);
                        this.focused_row_idx = next;
                        this.hovered_id = Some(key_rows[next].id.clone());
                        cx.stop_propagation();
                        cx.notify();
                    }
                    "home" => {
                        this.focused_row_idx = 0;
                        this.hovered_id = Some(key_rows[0].id.clone());
                        cx.stop_propagation();
                        cx.notify();
                    }
                    "end" => {
                        this.focused_row_idx = last;
                        this.hovered_id = Some(key_rows[last].id.clone());
                        cx.stop_propagation();
                        cx.notify();
                    }
                    "enter" => {
                        let id = key_rows[cur].id.clone();
                        this.hovered_id = Some(id.clone());
                        this.toggle_country_zoom(&id, cx);
                        cx.stop_propagation();
                    }
                    _ => {}
                }
            }))
            .child(list_body);

        let right_side = div()
            .when(!stack_layout, |d| {
                d.w(px(if compact_split { 268. } else { 336. }))
                    .flex_none()
                    .border_l_1()
                    .border_color(p.line_strong)
            })
            .when(stack_layout, |d| {
                d.w_full().border_t_1().border_color(p.line_strong)
            })
            .min_h_0()
            .pt(px(14.))
            .px(px(if compact_split { 12. } else { 14. }))
            .pb(px(6.))
            .flex()
            .flex_col()
            .child(measure_seg)
            .child(div().mt(px(10.)).child(col_head))
            .child(list_scroll);

        let split_card = div()
            .w_full()
            .when(!stack_layout, |d| d.flex_1().min_h(px(460.)))
            .rounded(px(10.))
            .bg(p.card)
            .border_1()
            .border_color(p.line)
            .overflow_hidden()
            .flex()
            .when(stack_layout, |d| d.flex_col())
            .child(map_col)
            .child(right_side);

        let mw_cell = self.measured_width.clone();
        let pb_cell = self.page_bounds.clone();
        let sensor = canvas(
            move |bounds, w, _| {
                let bw = f32::from(bounds.size.width);
                if bw > 40.0 {
                    let prev = mw_cell.get();
                    mw_cell.set(bw);
                    if (prev - bw).abs() > 1.0 {
                        w.request_animation_frame();
                    }
                }
                pb_cell.set(Some(bounds));
            },
            |_, _, _, _| (),
        )
        .absolute()
        .top_0()
        .left_0()
        .right_0()
        .h(px(0.));

        let scroll = div()
            .id(pro_eid(&self.id, "scroll"))
            .size_full()
            .min_h_0()
            .overflow_y_scroll()
            .pt(px(if mobile {
                14.
            } else if compact_split {
                20.
            } else {
                28.
            }))
            .px(px(if mobile {
                12.
            } else if compact_split {
                18.
            } else {
                32.
            }))
            .pb(px(if mobile { 16. } else { 24. }))
            .flex()
            .flex_col()
            .gap(px(if mobile { 12. } else { 16. }))
            .child(header_block)
            .child(toolbar_row)
            .child(split_card);

        let mut page = div()
            .id(self.id.clone())
            .track_focus(&self.focus)
            .relative()
            .size_full()
            .min_h_0()
            .bg(p.panel)
            .on_key_down(cx.listener(|this, ev: &KeyDownEvent, _, cx| {
                if ev.keystroke.key == "escape"
                    && (this.open_popover.take().is_some() || this.hovered_id.take().is_some())
                {
                    cx.stop_propagation();
                    cx.notify();
                }
            }))
            .child(sensor)
            .child(scroll);

        if let Some(pop) = self.open_popover.or(self.last_popover)
            && let Some(overlay) = self.render_popover_overlay(pop, self.open_popover.is_some(), cx)
        {
            page = page.child(overlay);
        }

        page = page.child(pro_toast_banner(self.toast.clone()));
        page
    }
}

impl Render for BrandRegionsScreen {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        if self.standalone {
            return self.render_page(w, cx).into_any_element();
        }
        self.shell.clone().into_any_element()
    }
}

