#[cfg(test)]
mod tests {
    use super::{
        BrandMapZoom, BrandRegionsMeasure, BrandRegionsPeriod, BrandRegionsScreen, WORLD_COUNTRIES,
        country_continent_zoom, default_regions, format_answers_count, format_delta_pct,
        hit_test_data_country,
    };
    use gpui::TestAppContext;

    #[test]
    fn world_map_geometry_and_hit_test_locate_key_countries() {
        assert_eq!(WORLD_COUNTRIES.len(), 175);
        let rows = default_regions();
        // United States centroid (approx 223, 108 in 1000x440 world coordinates)
        let us = WORLD_COUNTRIES
            .iter()
            .find(|&&(id, _, _, _)| id == "840")
            .expect("US polygon exists");
        let hit = hit_test_data_country(us.1 as f32, us.2 as f32, &rows);
        assert_eq!(hit.as_deref(), Some("840"));
        assert_eq!(country_continent_zoom("840"), BrandMapZoom::Americas);
        assert_eq!(country_continent_zoom("276"), BrandMapZoom::Europe);
        assert_eq!(country_continent_zoom("392"), BrandMapZoom::Asia);
    }

    #[test]
    fn rankings_sort_by_active_measure_and_scale_by_period() {
        assert_eq!(format_answers_count(5_600), "5.6k");
        assert_eq!(format_delta_pct(14.5), "+14.5%");
        assert_eq!(format_delta_pct(-1.3), "−1.3%");

        let mut cx = TestAppContext::single();
        cx.update(crate::init);
        let (view, w) = cx.add_window_view(|_, cx| BrandRegionsScreen::new("test-br", cx));
        w.update(|_, cx| {
            view.update(cx, |s, cx| {
                let vis_rows = s.ranked_regions();
                assert_eq!(vis_rows.len(), 16);
                assert_eq!(vis_rows[0].name.as_ref(), "Mexico");
                assert!((vis_rows[0].visibility - 64.1).abs() < 0.05);

                s.set_measure(BrandRegionsMeasure::Sentiment, cx);
                let sent_rows = s.ranked_regions();
                assert_eq!(sent_rows[0].name.as_ref(), "Canada");

                s.set_period(BrandRegionsPeriod::Days30, cx);
                let scaled = s.ranked_regions();
                let mexico = scaled.iter().find(|r| r.id.as_ref() == "484").unwrap();
                assert!(mexico.visibility < 64.1 && mexico.visibility > 50.0);

                s.toggle_country_zoom("484", cx);
                assert_eq!(s.zoom(), BrandMapZoom::Americas);
                s.toggle_country_zoom("484", cx);
                assert_eq!(s.zoom(), BrandMapZoom::World);
            });
        });
    }
}

