/// Subtle dual-layer card elevation shadow matching the Pro surface hierarchy.
pub fn pro_card_shadow(dark: bool) -> Vec<BoxShadow> {
    if dark {
        vec![
            BoxShadow::new(px(0.), px(2.), black().opacity(0.38))
                .blur_radius(px(8.))
                .spread_radius(px(-1.)),
            BoxShadow::new(px(0.), px(1.), black().opacity(0.28)).blur_radius(px(2.)),
        ]
    } else {
        vec![
            BoxShadow::new(px(0.), px(4.), black().opacity(0.045))
                .blur_radius(px(12.))
                .spread_radius(px(-2.)),
            BoxShadow::new(px(0.), px(1.), black().opacity(0.055)).blur_radius(px(2.)),
        ]
    }
}

/// Rounded square tile showing an app or provider mark, with neutral fallback.
pub fn pro_app_tile(app: &str, side: f32, cx: &App) -> AnyElement {
    let p = ProPalette::get(cx);
    let lower = app.trim().to_ascii_lowercase();
    let radius = (side * 0.25).clamp(5., 8.);
    if lower == "stripe"
        && let Some(mark) = pro_app_artwork("stripe", side, cx)
    {
        return div()
            .size(px(side))
            .flex_none()
            .rounded(px(radius))
            .overflow_hidden()
            .child(mark)
            .into_any_element();
    }
    let mark_side = (side * 0.58).round();
    let content = if let Some(mark) = pro_app_artwork(app, mark_side, cx) {
        mark
    } else {
        let initial = person_initials(app);
        div()
            .text_size(px((side * 0.40).max(9.)))
            .font_weight(FontWeight::SEMIBOLD)
            .text_color(p.ink)
            .child(if initial.is_empty() {
                "A".to_string()
            } else {
                initial.chars().take(1).collect()
            })
            .into_any_element()
    };
    let tile_bg: Hsla = if p.dark {
        rgb(0x27272b).into()
    } else {
        rgb(0xffffff).into()
    };
    let bdr: Hsla = if p.dark {
        hsla(0., 0., 1., 0.09)
    } else {
        hsla(0., 0., 0., 0.065)
    };
    let mut tile = div()
        .size(px(side))
        .flex_none()
        .rounded(px(radius))
        .bg(tile_bg)
        .border_1()
        .border_color(bdr)
        .flex()
        .items_center()
        .justify_center()
        .child(content);
    if !p.dark && side >= 24. {
        tile = tile.shadow(vec![
            BoxShadow::new(px(0.), px(1.), black().opacity(0.05)).blur_radius(px(2.)),
        ]);
    }
    tile.into_any_element()
}

fn infer_agent_brand_key(seed: &str) -> Option<&'static str> {
    let s = seed.trim().to_ascii_lowercase();
    if s.is_empty() {
        return None;
    }
    if s.contains("claude")
        || s.contains("opus")
        || s.contains("sonnet")
        || s.contains("haiku")
        || s.contains("orchestrat")
        || s.contains("writer")
        || s.contains("research")
        || s.contains("lead")
        || s.contains("launch")
        || s.contains("support")
        || s.contains("planner")
        || s.contains("review")
        || s.contains("editor")
        || s.contains("fact")
        || s.contains("design")
        || s.contains("copy")
    {
        Some("claude")
    } else if s.contains("gpt")
        || s.contains("openai")
        || s.contains("codex")
        || s.contains("coder")
        || s.contains("code")
        || s.contains("release")
        || s.contains("inspect")
        || s.contains("engineer")
        || s.contains("build")
        || s.contains("test")
        || s.contains("commit")
        || s.contains("migrat")
        || s.contains("patch")
        || s.contains("deploy")
    {
        Some("openai")
    } else if s.contains("gemini")
        || s.contains("ops")
        || s.contains("analyst")
        || s.contains("search")
        || s.contains("data")
        || s.contains("triage")
        || s.contains("router")
        || s.contains("monitor")
        || s.contains("audit")
        || s.contains("sec")
    {
        Some("gemini")
    } else if s.contains("deepseek") {
        Some("deepseek")
    } else if s.contains("mistral") {
        Some("mistral")
    } else if s.contains("qwen") {
        Some("qwen")
    } else if s.contains("llama") || s.contains("meta") {
        Some("meta")
    } else if s.contains("grok") || s.contains("xai") {
        Some("xai")
    } else {
        None
    }
}

/// Render an AI model/agent mark tile (resolving provider artwork when recognizable, with 3x3 pixel fallback).
pub fn pro_agent_avatar(
    seed: &str,
    color: Hsla,
    side: f32,
    working: bool,
    elapsed_ms: f32,
    cx: &App,
) -> AnyElement {
    let p = ProPalette::get(cx);
    let reduced = Theme::global(cx).reduced_motion;
    let radius = (side * 0.28).clamp(5., 9.).round();
    let tile_bg: Hsla = if p.dark {
        rgb(0x232327).into()
    } else {
        rgb(0xffffff).into()
    };
    let pulse_a = if working && !reduced {
        let phase = (elapsed_ms / 1100.) * std::f32::consts::TAU;
        0.16 + 0.14 * (0.5 + 0.5 * phase.sin())
    } else {
        0.0
    };
    let bdr = if pulse_a > 0.01 {
        pro_mix_color(p.line, color, pulse_a * 2.2)
    } else if p.dark {
        hsla(0., 0., 1., 0.09)
    } else {
        hsla(0., 0., 0., 0.07)
    };

    if let Some(brand) = infer_agent_brand_key(seed)
        && let Some(mark) = pro_app_artwork(brand, (side * 0.58).round().max(11.), cx)
    {
        let mut wrap = div()
            .size(px(side))
            .flex_none()
            .rounded(px(radius))
            .bg(tile_bg)
            .border_1()
            .border_color(bdr)
            .flex()
            .items_center()
            .justify_center()
            .child(mark);
        if !p.dark && side >= 22. {
            wrap = wrap.shadow(vec![
                BoxShadow::new(px(0.), px(1.), black().opacity(0.045)).blur_radius(px(2.)),
            ]);
        }
        return wrap.into_any_element();
    }

    let cells = agent_pixel_cells(seed);
    let sq = if side <= 20. {
        3.
    } else if side <= 26. {
        3.5
    } else if side <= 34. {
        4.
    } else {
        5.
    };
    let gap = if side <= 20. {
        1.
    } else if side <= 26. {
        1.5
    } else {
        2.
    };

    let mut grid = div().flex().flex_col().gap(px(gap));
    for r in 0..3usize {
        let mut row_el = div().flex().items_center().gap(px(gap));
        for c in 0..3usize {
            let i = r * 3 + c;
            let on = cells[i];
            let alpha = if working && !reduced {
                let phase = ((elapsed_ms + AGENT_WAVE_MS[i]) / 1200.) * std::f32::consts::TAU;
                let wave = 0.60 + 0.40 * phase.cos();
                if on { wave } else { 0.16 * wave }
            } else if on {
                1.0
            } else {
                0.0
            };
            row_el = row_el.child(
                div()
                    .size(px(sq))
                    .rounded(px((sq * 0.25).max(0.8)))
                    .bg(color.opacity(alpha)),
            );
        }
        grid = grid.child(row_el);
    }

    div()
        .size(px(side))
        .flex_none()
        .rounded(px(radius))
        .bg(tile_bg)
        .border_1()
        .border_color(bdr)
        .flex()
        .items_center()
        .justify_center()
        .child(grid)
        .into_any_element()
}

/// Render a person or workspace avatar with deterministic soft hue and optional presence dot.
pub fn pro_person_avatar(
    name: &str,
    side: f32,
    square: bool,
    status: Option<ProPresence>,
    cx: &App,
) -> AnyElement {
    const HUES: [f32; 8] = [214., 152., 40., 22., 330., 268., 174., 196.];
    let p = ProPalette::get(cx);
    let h = HUES[person_hue_index(name)] / 360.;
    let (bg, fg) = if p.dark {
        (hsla(h, 0.28, 0.24, 1.0), hsla(h, 0.60, 0.80, 1.0))
    } else {
        (hsla(h, 0.70, 0.92, 1.0), hsla(h, 0.48, 0.36, 1.0))
    };
    let radius = if square {
        px((side * 0.30).round())
    } else {
        px(999.)
    };
    let fs = (side * 0.38).clamp(8.5, 14.);
    let initials = person_initials(name);
    let mut wrap = div().relative().size(px(side)).flex_none().child(
        div()
            .size_full()
            .rounded(radius)
            .bg(bg)
            .text_color(fg)
            .text_size(px(fs))
            .font_weight(FontWeight::SEMIBOLD)
            .flex()
            .items_center()
            .justify_center()
            .child(initials),
    );
    if let Some(st) = status {
        let dot_side = (side * 0.28).clamp(6., 10.);
        let dot_color = match st {
            ProPresence::Online => p.green,
            ProPresence::Away => p.amber,
            ProPresence::Busy => p.red,
        };
        wrap = wrap.child(
            div()
                .absolute()
                .right(px(if square { -1.5 } else { 0. }))
                .bottom(px(if square { -1.5 } else { 0. }))
                .size(px(dot_side))
                .rounded_full()
                .bg(dot_color)
                .border_1()
                .border_color(p.panel),
        );
    }
    wrap.into_any_element()
}

/// Button visual variant for Pro screen toolbars and inspectors.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ProBtnStyle {
    Primary,
    Secondary,
    Ghost,
    Danger,
}

type ProClickFn = Rc<dyn Fn(&ClickEvent, &mut Window, &mut App)>;

struct ProBtnAnim {
    hover: Slide,
    press: Slide,
    current_label: SharedString,
    prev_label: Option<SharedString>,
    current_icon: Option<ProIcon>,
    swap_clock: PhaseClock,
}

#[derive(IntoElement)]
struct ProBtnVisual {
    state_id: ElementId,
    label: SharedString,
    lead_icon: Option<ProIcon>,
    style: ProBtnStyle,
    small: bool,
    on_click: ProClickFn,
}

impl RenderOnce for ProBtnVisual {
    fn render(self, w: &mut Window, cx: &mut App) -> impl IntoElement {
        let p = ProPalette::get(cx);
        let h = if self.small { 28. } else { 32. };
        let pad_x = if self.small { 9. } else { 12. };
        let fs = if self.small { 12.5 } else { 13. };
        let icon_sz = if self.small { 13. } else { 14. };
        let (bg, hover_bg, fg, border) = match self.style {
            ProBtnStyle::Primary => (
                p.primary,
                pro_mix_color(p.primary, p.on_primary, 0.12),
                p.on_primary,
                transparent_black(),
            ),
            ProBtnStyle::Secondary => (p.card, p.chip_hover, p.ink, p.line_strong),
            ProBtnStyle::Ghost => (transparent_black(), p.hover, p.text, transparent_black()),
            ProBtnStyle::Danger => (
                p.red_soft,
                p.red.opacity(0.22),
                p.red_ink,
                p.red.opacity(0.28),
            ),
        };
        let label_init = self.label.clone();
        let icon_init = self.lead_icon;
        let st = w.use_keyed_state(self.state_id, cx, |_, _| ProBtnAnim {
            hover: Slide::snappy(0.),
            press: Slide::snappy(0.),
            current_label: label_init,
            prev_label: None,
            current_icon: icon_init,
            swap_clock: PhaseClock::default(),
        });
        let (hov, down, prev_lbl, swap_t) = st.update(cx, |s, cx| {
            if s.current_label != self.label || s.current_icon != self.lead_icon {
                let old = std::mem::replace(&mut s.current_label, self.label.clone());
                s.prev_label = Some(old);
                s.current_icon = self.lead_icon;
                s.swap_clock.restart(cx);
            }
            let age = s.swap_clock.time(0.18, w, cx);
            let t = (age / 0.18).clamp(0., 1.);
            if t >= 1. {
                s.prev_label = None;
            }
            (
                s.hover.get(w, cx).clamp(0., 1.),
                s.press.get(w, cx).clamp(0., 1.),
                s.prev_label.clone(),
                t,
            )
        });

        let face_bg = pro_mix_color(bg, hover_bg, hov);
        let fg_current = if self.style == ProBtnStyle::Ghost {
            pro_mix_color(fg, p.ink, hov * 0.85)
        } else {
            fg
        };
        let dark = p.dark;
        let style = self.style;
        let paint_face = canvas(
            |_, _, _| (),
            move |bounds, _, window, _| {
                let bw = f32::from(bounds.size.width);
                let bh = f32::from(bounds.size.height);
                if bw <= 1. || bh <= 1. {
                    return;
                }
                let ix = (bw * 0.022 * down).clamp(0., 2.2);
                let iy = (bh * 0.042 * down).clamp(0., 1.4);
                let rect = Bounds::new(
                    point(bounds.origin.x + px(ix), bounds.origin.y + px(iy)),
                    size(px((bw - 2. * ix).max(1.)), px((bh - 2. * iy).max(1.))),
                );
                let r = px(7.).min(rect.size.width / 2.).min(rect.size.height / 2.);
                if !dark
                    && hov > 0.02
                    && down < 0.7
                    && matches!(style, ProBtnStyle::Primary | ProBtnStyle::Secondary)
                {
                    let shadow_alpha = 0.045 * hov * (1. - down);
                    window.paint_quad(
                        fill(
                            Bounds::new(point(rect.origin.x, rect.origin.y + px(1.)), rect.size),
                            black().opacity(shadow_alpha),
                        )
                        .corner_radii(r),
                    );
                }
                if face_bg.a > 0.001 || border.a > 0.001 {
                    window.paint_quad(quad(
                        rect,
                        Corners::all(r),
                        face_bg,
                        Edges::all(px(if border.a > 0.001 { 1. } else { 0. })),
                        border,
                        BorderStyle::Solid,
                    ));
                }
            },
        )
        .absolute()
        .inset_0();

        let enter_ease = pro_ease(swap_t);
        let label_el = if let Some(old) = prev_lbl {
            let exit_ease = (1. - swap_t / 0.65).clamp(0., 1.);
            div()
                .relative()
                .flex()
                .items_center()
                .child(
                    div()
                        .relative()
                        .top(px(2.5 * (1. - enter_ease)))
                        .opacity(enter_ease)
                        .child(self.label.clone()),
                )
                .child(
                    div()
                        .absolute()
                        .left_0()
                        .top(px(-2.5 * (1. - exit_ease)))
                        .opacity(exit_ease)
                        .child(old),
                )
                .into_any_element()
        } else {
            div().child(self.label.clone()).into_any_element()
        };

        let on_click = self.on_click;
        div()
            .id("pro-btn-hit")
            .role(Role::Button)
            .aria_label(self.label)
            .tab_index(0)
            .flex_1()
            .h(px(h))
            .px(px(pad_x))
            .relative()
            .flex()
            .items_center()
            .justify_center()
            .rounded(px(7.))
            .text_color(fg_current)
            .text_size(px(fs))
            .font_weight(FontWeight::MEDIUM)
            .whitespace_nowrap()
            .cursor_pointer()
            .focus_visible(move |s| s.border_1().border_color(p.focus))
            .on_hover({
                let st = st.clone();
                move |inside, w, cx| {
                    st.update(cx, |s, cx| {
                        s.hover.set(if *inside { 1. } else { 0. }, cx);
                        if !*inside {
                            s.press.set(0., cx);
                        }
                        cx.notify();
                    });
                    w.refresh();
                }
            })
            .on_mouse_down(MouseButton::Left, {
                let st = st.clone();
                move |_, w, cx| {
                    st.update(cx, |s, cx| {
                        s.press.set(1., cx);
                        cx.notify();
                    });
                    w.refresh();
                }
            })
            .on_mouse_up(MouseButton::Left, {
                let st = st.clone();
                move |_, w, cx| {
                    st.update(cx, |s, cx| {
                        s.press.set(0., cx);
                        cx.notify();
                    });
                    w.refresh();
                }
            })
            .on_mouse_up_out(MouseButton::Left, {
                let st = st.clone();
                move |_, w, cx| {
                    st.update(cx, |s, cx| {
                        s.press.set(0., cx);
                        cx.notify();
                    });
                    w.refresh();
                }
            })
            .on_key_down({
                let st = st.clone();
                move |ev, w, cx| {
                    if matches!(ev.keystroke.key.as_str(), "enter" | "space") {
                        st.update(cx, |s, cx| {
                            s.press.set(1., cx);
                            cx.notify();
                        });
                        w.refresh();
                    }
                }
            })
            .on_key_up({
                let st = st.clone();
                move |ev, w, cx| {
                    if matches!(ev.keystroke.key.as_str(), "enter" | "space") {
                        st.update(cx, |s, cx| {
                            s.press.set(0., cx);
                            cx.notify();
                        });
                        w.refresh();
                    }
                }
            })
            .on_click(move |ev, w, cx| (on_click)(ev, w, cx))
            .child(paint_face)
            .child(
                div()
                    .relative()
                    .top(px(0.5 * down))
                    .flex()
                    .items_center()
                    .justify_center()
                    .gap(px(5.))
                    .when_some(self.lead_icon, |d, ic| {
                        d.child(
                            div()
                                .opacity(if swap_t < 1. { enter_ease } else { 1. })
                                .child(pro_icon(ic, icon_sz * (1. - 0.05 * down), fg_current)),
                        )
                    })
                    .child(label_el),
            )
    }
}

