        side,
        rounded_square,
        active_color,
    }
    .into_any_element()
}

struct ProSwapLabelState {
    current: SharedString,
    prev: Option<SharedString>,
    clock: PhaseClock,
}

#[derive(IntoElement)]
struct ProSwapLabel {
    id: ElementId,
    text: SharedString,
    font_size: f32,
    weight: FontWeight,
    color: Hsla,
}

impl RenderOnce for ProSwapLabel {
    fn render(self, w: &mut Window, cx: &mut App) -> impl IntoElement {
        let init_txt = self.text.clone();
        let st = w.use_keyed_state(pro_eid(&self.id, "swlbl"), cx, |_, _| ProSwapLabelState {
            current: init_txt,
            prev: None,
            clock: PhaseClock::default(),
        });
        let (prev, t) = st.update(cx, |s, cx| {
            if s.current != self.text {
                let old = std::mem::replace(&mut s.current, self.text.clone());
                s.prev = Some(old);
                s.clock.restart(cx);
            }
            let age = s.clock.time(0.18, w, cx);
            let u = (age / 0.18).clamp(0., 1.);
            if u >= 1. {
                s.prev = None;
            }
            (s.prev.clone(), u)
        });
        let enter_t = pro_ease(t);
        if let Some(old) = prev {
            let exit_t = (1. - t / 0.65).clamp(0., 1.);
            div()
                .relative()
                .flex()
                .items_center()
                .text_size(px(self.font_size))
                .font_weight(self.weight)
                .text_color(self.color)
                .whitespace_nowrap()
                .child(
                    div()
                        .relative()
                        .top(px(2.8 * (1. - enter_t)))
                        .opacity(enter_t)
                        .child(self.text),
                )
                .child(
                    div()
                        .absolute()
                        .left_0()
                        .top(px(-2.8 * (1. - exit_t)))
                        .opacity(exit_t)
                        .child(old),
                )
                .into_any_element()
        } else {
            div()
                .text_size(px(self.font_size))
                .font_weight(self.weight)
                .text_color(self.color)
                .whitespace_nowrap()
                .child(self.text)
                .into_any_element()
        }
    }
}

