struct ProToastAnimState {
    hovered: bool,
    paused_accum_secs: f32,
    pause_started: Option<Instant>,
    last_origin: Option<Instant>,
}

#[derive(IntoElement)]
struct ProToastBanner {
    toast: Option<(SharedString, Instant)>,
}

impl RenderOnce for ProToastBanner {
    fn render(self, w: &mut Window, cx: &mut App) -> impl IntoElement {
        let Some((msg, started)) = self.toast else {
            return div().into_any_element();
        };
        let st = w.use_state(cx, |_, _| ProToastAnimState {
            hovered: false,
            paused_accum_secs: 0.,
            pause_started: None,
            last_origin: Some(started),
        });
        let (effective_elapsed, hovered) = st.update(cx, |s, _| {
            if s.last_origin != Some(started) {
                s.last_origin = Some(started);
                s.paused_accum_secs = 0.;
                s.pause_started = s.hovered.then(Instant::now);
            }
            let live_pause = s
                .pause_started
                .map(|t0| t0.elapsed().as_secs_f32())
                .unwrap_or(0.);
            let raw = started.elapsed().as_secs_f32();
            ((raw - s.paused_accum_secs - live_pause).max(0.), s.hovered)
        });
        let lifetime = 2.60;
        if effective_elapsed >= lifetime {
            return div().into_any_element();
        }
        let reduced = disabled_motion(cx);
        if !reduced && !hovered {
            w.request_animation_frame();
        }
        let t = if reduced {
            1.0
        } else if effective_elapsed < 0.22 {
            pro_ease(effective_elapsed / 0.22)
        } else if effective_elapsed > lifetime - 0.28 {
            1. - pro_ease((effective_elapsed - (lifetime - 0.28)) / 0.28)
        } else {
            1.0
        };
        let p = ProPalette::get(cx);
        div()
            .id("pro-toast-banner-hit")
            .on_hover({
                let st = st.clone();
                move |inside, w, cx| {
                    st.update(cx, |s, cx| {
                        if *inside && !s.hovered {
                            s.hovered = true;
                            s.pause_started = Some(Instant::now());
                        } else if !*inside && s.hovered {
                            s.hovered = false;
                            if let Some(t0) = s.pause_started.take() {
                                s.paused_accum_secs += t0.elapsed().as_secs_f32();
                            }
                        }
                        cx.notify();
                    });
                    w.refresh();
                }
            })
            .absolute()
            .bottom(px(16. - 8. * (1. - t)))
            .right(px(16.))
            .opacity(t)
            .h(px(34.))
            .px(px(12.))
            .rounded(px(8.))
            .bg(if p.dark { rgb(0x232327) } else { rgb(0x18181b) })
            .border_1()
            .border_color(if p.dark {
                p.line_strong
            } else {
                hsla(0., 0., 1., 0.12)
            })
            .shadow_md()
            .flex()
            .items_center()
            .gap(px(7.))
            .text_size(px(12.5))
            .font_weight(FontWeight::MEDIUM)
            .text_color(rgb(0xffffff))
            .child(pro_check_draw("pro-toast-chk", true, 15., false, p.green))
            .child(pro_swap_label(
                "pro-toast-lbl",
                msg,
                12.5,
                FontWeight::MEDIUM,
                rgb(0xffffff).into(),
            ))
            .into_any_element()
    }
}

/// Animated floating toast banner (`2.4s` window with smooth spring slide-in and fade-out).
pub fn pro_toast_banner(toast: Option<(SharedString, Instant)>) -> AnyElement {
    ProToastBanner { toast }.into_any_element()
}

#[derive(IntoElement)]
struct ProShimmerText {
    id: ElementId,
    text: SharedString,
    base_color: Hsla,
    highlight_color: Hsla,
    font_size: f32,
    weight: FontWeight,
    active: bool,
}

impl RenderOnce for ProShimmerText {
    fn render(self, w: &mut Window, cx: &mut App) -> impl IntoElement {
        let reduced = disabled_motion(cx);
        if !self.active || reduced {
            return div()
                .text_size(px(self.font_size))
                .font_weight(self.weight)
                .text_color(self.base_color)
                .child(self.text)
                .into_any_element();
        }
        let st = w.use_keyed_state(pro_eid(&self.id, "shim"), cx, |_, _| Instant::now());
        let started = *st.read(cx);
        w.request_animation_frame();
        let phase = (started.elapsed().as_secs_f32() / 1.65).fract();
        let chars: Vec<char> = self.text.chars().collect();
        let n = chars.len().max(1) as f32;
        let center = -0.25 + phase * 1.50;
        let mut row = div()
            .flex()
            .flex_wrap()
            .items_center()
            .min_w_0()
            .text_size(px(self.font_size))
            .font_weight(self.weight);
        let char_color = |idx: usize| {
            let u = idx as f32 / n;
            let dist = ((u - center) / 0.22).abs();
            let glint = (1. - dist).clamp(0., 1.);
            let glint = glint * glint * (3. - 2. * glint);
            pro_mix_color(self.base_color, self.highlight_color, glint)
        };
        let mut idx = 0usize;
        while idx < chars.len() {
            let ch = chars[idx];
            if ch == ' ' {
                row = row.child(div().w(px(self.font_size * 0.27)).h(px(self.font_size)));
                idx += 1;
            } else if ch > '\u{2e7f}' {
                let col = char_color(idx);
                row = row.child(div().text_color(col).child(ch.to_string()));
                idx += 1;
            } else {
                let mut word = div().flex().items_center();
                while idx < chars.len() && chars[idx] != ' ' && chars[idx] <= '\u{2e7f}' {
                    let col = char_color(idx);
                    word = word.child(div().text_color(col).child(chars[idx].to_string()));
                    idx += 1;
                }
                row = row.child(word);
            }
        }
        row.into_any_element()
    }
}

